class Vault < BasicObject                  # proxy base: minimal inherited surface
  def initialize(store, policy, who)
    @store, @policy, @who = store, policy, who
  end
  def method_missing(name, *args, &blk)
    ::Kernel.raise ::AccessDenied, name unless @policy.allows(@who, name)
    @store.public_send(name, *args, &blk)  # public_send keeps private API private
  end
  def respond_to_missing?(name, include_private = false) = @store.respond_to?(name)
end
